#ifndef SOIL_SENSOR_H
#define SOIL_SENSOR_H

#include <stdint.h>
#include "ipc.h"

#define GT_SOIL_I2C_ADDR 0x36    /* Adafruit STEMMA (seesaw) */

typedef struct gt_soil_sensor gt_soil_sensor;

/* i2c_dev: e.g. "/dev/i2c-1" */
gt_soil_sensor *gt_soil_open(const char *i2c_dev);
gt_status       gt_soil_read(gt_soil_sensor *s, uint32_t *raw_out);
void            gt_soil_close(gt_soil_sensor *s);

#endif
==== include/hub.h
#ifndef HUB_H
#define HUB_H

#include <stdint.h>
#include "ipc.h"

typedef struct gt_hub gt_hub;

gt_hub   *gt_hub_create(void);
/* Validate a message, stamp seq + time, and fill `out` for forwarding. */
gt_status gt_hub_accept(gt_hub *h, const gt_msg *in, uint64_t now_us, gt_msg *out);
/* Per-sensor last-seen check; returns number of timed-out sensors. */
int       gt_hub_check_timeouts(gt_hub *h, uint64_t now_us);
void      gt_hub_destroy(gt_hub *h);

#endif
==== include/supervisor.h
#ifndef SUPERVISOR_H
#define SUPERVISOR_H

#include <stdint.h>
#include "ipc.h"

typedef struct gt_supervisor gt_supervisor;

gt_supervisor *gt_sup_create(void);
/* Register a child by argv; started in dependency order. */
gt_status      gt_sup_add_child(gt_supervisor *s, const char *name, char *const argv[]);
/* One poll() iteration: reap SIGCHLD, check heartbeats, restart with backoff. */
gt_status      gt_sup_step(gt_supervisor *s, uint64_t now_ms);
void           gt_sup_destroy(gt_supervisor *s);

#endif
==== include/log_record.h
#ifndef LOG_RECORD_H
#define LOG_RECORD_H

#include <stddef.h>
#include <stdint.h>
#include "ipc.h"

/* On-disk format: see DESIGN.md "In what format". Little-endian, packed. */
#define GT_SEG_MAGIC      "GTLG"
#define GT_SEG_VERSION    1
#define GT_SEG_HEADER_SZ  16
#define GT_REC_MAGIC      0xA7
#define GT_REC_VERSION    1
#define GT_REC_SIZE       24

typedef enum { GT_REC_DATA = 0x01, GT_REC_GAP = 0x02 } gt_rec_type;

typedef struct {
    uint8_t  type;       /* gt_rec_type */
    uint8_t  sensor_id;  /* gt_sensor_id */
    uint32_t seq;
    uint64_t timestamp_us;
    uint32_t value;      /* DATA: raw count; GAP: refused-reading count */
} gt_record;

uint32_t  gt_crc32(const void *buf, size_t len);
gt_status gt_record_encode(const gt_record *rec, uint8_t out[GT_REC_SIZE]);
gt_status gt_record_decode(const uint8_t in[GT_REC_SIZE], gt_record *rec);

#endif
